// ── Helper: retorna o versículo do dia (determinístico por data) ──────────
export function getVerseOfDay(): DailyVerse {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = now.getTime() - start.getTime();
  const oneDay = 1000 * 60 * 60 * 24;
  const dayOfYear = Math.floor(diff / oneDay); // 1–366
  return DAILY_VERSES[(dayOfYear - 1) % DAILY_VERSES.length];
}

